(() => {
  const syntax = [...document.querySelectorAll('h2')].find(h => h.textContent.trim() === 'Syntax');
  const html = syntax.parentElement ? syntax.parentElement.innerHTML.slice(0, 30000) : '';
  // pull out the signature code blocks (MDN uses <pre class="language-text"> containing the method signature)
  const preBlocks = [...(syntax.parentElement.parentElement.querySelectorAll('pre'))].map(p => p.textContent.trim());
  return preBlocks.join('\n---\n');
})()

