(() => {
  const items = [];
  document.querySelectorAll('pre').forEach((p, i) => {
    const t = p.textContent;
    if (t.includes('roundRect') || t.includes('radius')) items.push('PRE' + i + ': ' + t);
  });
  return items.length ? items.join('\n---\n') : 'no pre matched; total pres: ' + document.querySelectorAll('pre').length;
})()

(() => {
  const c = document.createElement('canvas');
  c.width = 120; c.height = 80;
  c.style.cssText = 'position:absolute;left:0;top:0';
  document.body.appendChild(c);
  const ctx = c.getContext('2d');
  ctx.beginPath();
  ctx.roundRect(20, 10, 80, 60, [10, 20, 30, 40]);
  ctx.fillStyle = '#ff0000';
  ctx.fill();
  const d = ctx.getImageData(0, 0, 120, 80).data;
  let opaque = 0, red = 0, center = null;
  const rows = [];
  for (let y = 0; y < 80; y++) {
    let rowCount = 0;
    for (let x = 0; x < 120; x++) {
      const i = (y * 120 + x) * 4;
      if (d[i + 3] > 0) opaque++;
      if (d[i + 3] > 0 && d[i] > 200 && d[i + 1] < 100) { red++; rowCount++; }
    }
    if (y === 40) center = [d[40*120*4 + 10], d[40*120*4 + 11], d[40*120*4 + 12], d[40*120*4 + 13]];
    rows.push(rowCount);
  }
  return JSON.stringify({
    totalPixels: 120 * 80,
    opaquePixels: opaque,
    redFilledPixels: red,
    centerPixel_rgba: center,
    redPerRow: { row11: rows[11], row40: rows[40], row70: rows[70], row0: rows[0], row79: rows[79] },
    // corner checks: with radii [10,20,30,40] => TL=10, TR=20, BR=30, BL=40
    // TL corner (row 11-12 near left edge x=20): pixels at x=20..23 should be mostly outside the rounded region
    tlEdge: Array.from({length: 8}, (_, i) => [d[12*120*4 + (20+i)*4], d[12*120*4 + (20+i)*4+3]]),
    brEdge: Array.from({length: 10}, (_, i) => [d[68*120*4 + (99-i)*4], d[68*120*4 + (99-i)*4+3]])
  });
})()

(() => {
  const c = document.createElement('canvas');
  c.width = 200; c.height = 120;
  document.body.appendChild(c);
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#ff0000';
  // (a) object form
  ctx.beginPath();
  ctx.roundRect(0, 0, 60, 60, { x: 15, y: 30 });
  ctx.fill();
  // (b) mixed list: number + object
  ctx.beginPath();
  ctx.roundRect(70, 0, 60, 60, [12, { x: 25, y: 25 }]);
  ctx.fill();
  // (c) DOMPoint instance
  ctx.beginPath();
  ctx.roundRect(140, 0, 60, 60, new DOMPoint(20, 20));
  ctx.fill();
  // (d) RangeError check
  let err = 'none';
  try { ctx.beginPath(); ctx.roundRect(0, 70, 60, 40, [1, 2, 3, 4, 5]); } catch (e) { err = e.name + ': ' + e.message; }
  const d = ctx.getImageData(0, 0, 200, 120).data;
  const sample = (x, y) => { const i = (y * 200 + x) * 4; return [d[i], d[i+1], d[i+2], d[i+3]]; };
  return JSON.stringify({
    topRightCorner_of_a: sample(59, 0),        // radii {x:15,y:30} -> TL=TR=15, BR=BL=30 => TR is cut => transparent
    topRightCorner_of_b: sample(129, 0),       // [12,{25,25}] -> TL=BR=12, TR=BL=25 => TR cut => transparent
    topRightCorner_of_c: sample(199, 0),       // single DOMPoint(20,20) => all corners 20 => cut => transparent
    center_a: sample(30, 30), center_b: sample(100, 30), center_c: sample(170, 30),
    rangeError: err
  });
})()
